import{z as i,x as l,o as E,c as B,q as t,j as n,D as e,d as A,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"协议栈实践收束","description":"","frontmatter":{"title":"协议栈实践收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/npk-map.md","filePath":"cs/npk-map.md","lastUpdated":1791063341000}'),p={name:"cs/npk-map.md"};function d(c,a,m,D,C,_){const s=l("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="协议栈实践收束" tabindex="-1">协议栈实践收束 <a class="header-anchor" href="#协议栈实践收束" aria-label="Permalink to &quot;协议栈实践收束&quot;">​</a></h1><div class="epigraph"><p>读协议栈读到最后一课，拿走的不是函数名清单，而是四条不变的骨架：状态有地址、转移有动作、排队有预算、拒绝有计数。</p><footer>—— 据 Benvenuti, <em>Understanding Linux Network Internals</em>；Stevens, <em>TCP/IP Illustrated</em>；RFC 9293 对照整理</footer></div><p><a href="/cs/npk-debugging-tools">上一课</a>给了从症状到层的判定序。本课程到此收束：本课把五课拼回一张图——一个包从网卡到进程、再从进程回到网卡的完整旅程——并把这一层实践沉淀出的共同原理收在四条骨架上，给主干课的「为什么这样设计」补上「落进代码是什么样」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的是：读完五课，换成另一套协议栈（另一内核版本、用户态栈、甚至 QUIC 的用户态实现）时，哪些知识跟着版本走、哪些不跟。不这么做会错在哪：把函数名与 sysctl 名当知识带走，版本一换全部作废；把主干课的协议语义与本课程的对象账混成一层，就分不清「TIME_WAIT 该不该有」（协议问题）与「tw 桶满了谁被淘汰」（实现问题）——两者都真实，但答案属于不同的书。</p><p><span class="marginnote">直觉类比：函数名与 sysctl 名像某条公交线路的站牌——换一条线路（换内核版本）就全部作废；「状态有地址、排队有预算、拒绝有计数」则像「城市要有路网、红绿灯和收费站」这类规律——换一座城市照样适用。本课要带走的是后者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拼图按一个包的旅程走。<a href="/cs/npk-rx-path">收包路径</a>：DMA 进环、中断只通知、软中断按预算轮询、GRO 合并、四元组查出 sock、计入 rmem、<code>sk_data_ready</code> 唤醒。<a href="/cs/npk-tcp-state-machine">TCP 状态机</a>：同一逻辑连接按态分家——LISTEN 两队列、ESTABLISHED 哈希表、TIME_WAIT 小对象、close 之后的孤儿。<a href="/cs/npk-congestion-implementation">拥塞控制</a>：窗口只在 ACK 路径上被改，算法可插拔，节奏由 pacing 与 qdisc 分管。<a href="/cs/npk-socket-layer">套接字层</a>：fd、BSD 套接字、协议 sock 三层映射，等待队列把软中断的生产与进程的消费会合。<a href="/cs/npk-debugging-tools">调试工具</a>：沿同一张图逆向查计数器，从网卡环一路查到 socket 队列。正向读是理解，逆向查是排障，同一张图两个方向。</p><p><span class="marginnote">术语翻译：「孤儿 socket」不是泄漏——进程已调用 close() 放手，但连接还没干净收尾（如 FIN 还没发完、数据还在排队），内核暂时替它兜底。它没有 fd、应用够不着，只能靠内核计数器观测；兜底失败才真正释放。</span></p>',9)),(E(),n(o,null,{default:e(()=>[r(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NIC%5B%22%E6%94%B6%E5%8C%85%E8%B7%AF%E5%BE%84%EF%BC%9A%E7%8E%AF%20%E2%86%92%20%E8%BD%AF%E4%B8%AD%E6%96%AD%20%E2%86%92%20%E9%98%9F%E5%88%97%20%E2%86%92%20%E5%94%A4%E9%86%92%22%5D%20--%3E%20TCP%5B%22%E7%8A%B6%E6%80%81%E6%9C%BA%EF%BC%9A%E6%8C%89%E6%80%81%E5%88%86%E5%AE%B6%E7%9A%84%E5%AF%B9%E8%B1%A1%E4%B8%8E%E8%A1%A8%22%5D%0A%20%20TCP%20--%3E%20CC%5B%22%E6%8B%A5%E5%A1%9E%E6%8E%A7%E5%88%B6%EF%BC%9AACK%20%E8%B7%AF%E5%BE%84%E4%B8%8A%E7%9A%84%E7%AA%97%E5%8F%A3%E8%B4%A6%22%5D%0A%20%20CC%20--%3E%20SOCK%5B%22%E5%A5%97%E6%8E%A5%E5%AD%97%E5%B1%82%EF%BC%9Afd%20%E5%88%B0%20sock%20%E7%9A%84%E6%98%A0%E5%B0%84%E4%B8%8E%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%22%5D%0A%20%20SOCK%20--%3E%20DBG%5B%22%E8%B0%83%E8%AF%95%E5%B7%A5%E5%85%B7%EF%BC%9A%E6%B2%BF%E5%9B%BE%E9%80%86%E5%90%91%E6%9F%A5%E8%AE%A1%E6%95%B0%E5%99%A8%22%5D%0A%20%20DBG%20--%3E%7C%22%E5%9B%9E%E5%88%B0%22%7C%20NIC%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四条骨架在五课里各出现至少一次。状态有地址：状态存哪张表、哪个字段，决定查找成本、生命周期与它出现在哪个计数器里——找不到地址的状态无法观测也无法回收。转移有动作：状态机的边携带发段、起定时器、清记账，图是抽象，边才是程序。排队有预算：软中断预算、SYN 队列、accept 队列、rmem/wmem——栈里没有无限的东西，满了各有各的拒绝方式。拒绝有计数：每个拒绝点都留一个名字，这是排障判定序能成立的全部前提。这四条也是检验新栈的尺子：用户态协议栈把内核的函数换成自己的，但只要状态仍可寻址、队列仍有预算、拒绝仍留计数，<a href="/cs/npk-debugging-tools">上一课</a>的判定序就换汤不换药；反之，<a href="/cs/hpc-kernel-bypass">内核旁路</a>卖掉内核服务时，卖掉的正是这四条的实现者——状态、计数、预算全要自建，那份代价清单旁路课已经列过。往更深走，<a href="/cs/hpc-map">高性能网络</a>的路径下移与本课程的路径解剖互为里外：一个从瓶颈往下换栈，一个从线缆往上读栈。</p><p><span class="marginnote">一个自查口径：读完本课程后，遇到「连接慢」，应能不查资料说出至少四个候选丢包点与各自的计数器名——网卡环 miss、softnet_stat 挤兑、ListenDrops、RcvPruned。说不全，说明读到的还是工具清单而不是结构。</span></p><p><span class="marginnote">数字实例：Linux 的 TIME_WAIT 固定停 60 秒（2MSL）。对同一个目标地址端口，进程可用的源端口约 6.4 万个（16 比特），也就是说向同一目标发起短连接的速率上限约 \\(64000/60 \\approx 1000\\) 次/秒——压测打满这条线就会「无法分配端口」，而当时 CPU 和带宽都很空闲。</span></p>',4)),(E(),n(o,null,{default:e(()=>[r(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%80%E4%B8%AA%E5%8C%85%E5%8F%AF%E8%83%BD%E5%9C%A8%E5%93%AA%E8%A2%AB%E6%8B%92%3F%22%5D%20--%3E%20D1%5B%22%E7%BD%91%E5%8D%A1%E7%8E%AF%E6%BB%A1%3A%20rx_missed%22%5D%0A%20%20Q%20--%3E%20D2%5B%22%E8%BD%AF%E4%B8%AD%E6%96%AD%E9%A2%84%E7%AE%97%E5%B0%BD%3A%20softnet%20dropped%22%5D%0A%20%20Q%20--%3E%20D3%5B%22SYN%2Faccept%20%E9%98%9F%E5%88%97%E6%BB%A1%3A%20ListenDrops%22%5D%0A%20%20Q%20--%3E%20D4%5B%22socket%20%E7%BC%93%E5%86%B2%E6%BB%A1%3A%20RcvPruned%22%5D%0A%20%20Q%20--%3E%20D5%5B%22%E5%BA%94%E7%94%A8%E4%B8%8D%20read%3A%20%E9%98%9F%E5%88%97%E6%BB%9E%E7%95%99%22%5D%0A%20%20D1%20--%3E%20C1%5B%22%E6%AF%8F%E5%A4%84%E9%83%BD%E6%9C%89%E8%AE%A1%E6%95%B0%E5%99%A8%E5%8F%AF%E6%9F%A5%22%5D%0A%20%20D2%20--%3E%20C1%0A%20%20D3%20--%3E%20C1%0A%20%20D4%20--%3E%20C1%0A%20%20D5%20--%3E%20C1%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不写特定版本内核的源码导读，函数名随版本漂；不写 eBPF 数据面编程与 <a href="/cs/virt-network-virtualization">网络虚拟化</a>的数据面；QUIC 的用户态实现只在对照里点名，不在本课程展开。主干课继续答协议设计，本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五课拼成一张双向图：正向是包的旅程，逆向是排障的判定序。</li><li>四条骨架跨版本成立：状态有地址、转移有动作、排队有预算、拒绝有计数。</li><li>协议语义（该不该有）与实现对象（在哪、满没满）分层作答，不混为一谈。</li><li>内核旁路卖掉的正是这四条的内核实现者，自建代价是选型的一等输入。</li><li>出处：Benvenuti, <em>Understanding Linux Network Internals</em>；Stevens, <em>TCP/IP Illustrated</em>；RFC 9293；据本课程五课的对象与计数器口径整理。</li></ul>',4))])}const u=i(p,[["render",d]]);export{f as __pageData,u as default};
